<?php
require __DIR__.'/../lib/bootstrap.php';require_admin();require_csrf();
try{$slot=$_POST['slot_key']??'';$q=db()->prepare('SELECT * FROM site_media_slots WHERE slot_key=?');$q->execute([$slot]);$s=$q->fetch();if(!$s)throw new RuntimeException('Espacio de medios no válido.');db()->beginTransaction();
if(($_POST['action']??'')==='restore'){$h=db()->prepare('SELECT * FROM site_media_history WHERE id=? AND slot_id=?');$h->execute([(int)$_POST['history_id'],$s['id']]);$old=$h->fetch();if(!$old)throw new RuntimeException('La versión no pertenece a este espacio.');db()->prepare('INSERT INTO site_media_history(slot_id,path,focal_x,focal_y) VALUES(?,?,?,?)')->execute([$s['id'],$s['path'],$s['focal_x'],$s['focal_y']]);db()->prepare('UPDATE site_media_slots SET path=?,focal_x=?,focal_y=? WHERE id=?')->execute([$old['path'],$old['focal_x'],$old['focal_y'],$s['id']]);}
else{$u=upload('media',$s['media_type']);db()->prepare('INSERT INTO site_media_history(slot_id,path,focal_x,focal_y) VALUES(?,?,?,?)')->execute([$s['id'],$s['path'],$s['focal_x'],$s['focal_y']]);db()->prepare('UPDATE site_media_slots SET path=?,focal_x=?,focal_y=? WHERE id=?')->execute([$u['path'],$s['media_type']==='image'?(int)($_POST['focal_x']??50):50,$s['media_type']==='image'?(int)($_POST['focal_y']??50):50,$s['id']]);}db()->commit();json_response(['ok'=>true]);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();json_response(['error'=>$e->getMessage()],422);}
